    if (e >= 0) { dan_str old = d->vals[e]; d->vals[e] = dan_str_share(v); dan_str_release(old); (void)old; return; }
    if (d->n == d->cap) dm_Dis_grow(d);
    e = d->n++;
    d->keys[e] = DAN_ID(k); d->vals[e] = dan_str_share(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
